 * This generated file contains a sample Java library project to get you
 * started.  For more details on building Java & JVM projects, please refer
 * to https://docs.gradle.org/9.7.1/userguide/building_java_projects.html
 * in the Gradle documentation.
 */

plugins {
    // Apply the java-library plugin for API and implementation separation.
    `java-library`
}

group = "org.rapidcow.trivnote"
// Bump this in gradle.properties!
version = project.findProperty("VERSION_NAME") as String

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // This dependency is exported to consumers, that is to say found on their compile classpath.
    api(libs.commons.math3)

    // This dependency is used internally, and not exposed to consumers on their own compile classpath.
    implementation(libs.guava)
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}

tasks.javadoc {
    (options as StandardJavadocDocletOptions).apply {
        // Enable all documentation checks
        addBooleanOption("Xdoclint:all", true)
        // Suppress routine progress output
        addBooleanOption("quiet", true)
        // UTF-8 all the way!
        encoding = "UTF-8"
        charSet  = "UTF-8"
        docEncoding = "UTF-8"
    }
}
